package dev.reckless.tvlauncher;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.content.ClipData;import android.content.ClipboardManager;import android.content.Context;import android.widget.*;import android.view.*;
public class DeviceToolsActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(16,21,28));sc.setPadding(dp(30),dp(22),dp(30),dp(26));LinearLayout box=new LinearLayout(this);box.setOrientation(1);sc.addView(box);setContentView(sc);
 text(box,"ADB SETUP & RECOVERY",true);text(box,"This page explains optional computer/ADB setup. Reckless TV does not silently modify system packages.",false);text(box,"ENABLE ADB ON FIRE TV",true);text(box,"1. Open Settings > My Fire TV > About.\n2. Select the device name repeatedly until Developer Options are enabled.\n3. Open Developer Options and enable ADB Debugging.\n4. Connect from a trusted computer on the same network and approve the authorization prompt.\n5. Keep the stock Amazon launcher installed as your recovery path.",false);text(box,"HOME BUTTON LIMITATION",true);text(box,"A third-party HOME intent filter may be offered by Fire OS, but the physical Home button can still force Amazon Home. Reliable redirection can require an accessibility service and ADB-granted permissions; behavior varies by Fire OS build. This build does not claim to override the Home button.",false);text(box,"DEBLOAT SAFETY",true);text(box,"No package-disabling catalogue is enabled here. Amazon package names and dependencies vary by model and firmware, and disabling the wrong component can break settings, updates, remotes, networking, or recovery. Do not run random debloat lists. Keep changes reversible and record every package you change.",false);text(box,"RECOVERY COMMANDS",true);text(box,"From an authorized ADB shell, inspect before changing anything:\n\nadb shell pm list packages -d\n\nadb shell pm list packages\n\nTo re-enable a package you personally disabled (replace PACKAGE):\n\nadb shell pm enable PACKAGE\n\nTo restore Amazon Home, identify the actual launcher package on your device first; do not guess its package name. Use Fire TV Settings to reset the default Home choice if that option is available.",false);Button copy=new Button(this);copy.setText("COPY RECOVERY COMMAND");box.addView(copy);copy.setOnClickListener(v->{String s="adb shell pm list packages -d\nadb shell pm enable PACKAGE";((ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("ADB recovery",s));Toast.makeText(this,"Commands copied",Toast.LENGTH_SHORT).show();});Button done=new Button(this);done.setText("DONE");box.addView(done);done.setOnClickListener(v->finish());}
 private void text(LinearLayout box,String s,boolean heading){TextView t=new TextView(this);t.setText(s);t.setTextColor(heading?Color.rgb(26,174,102):Color.WHITE);t.setTextSize(heading?13:16);t.setPadding(0,dp(heading?15:5),0,dp(8));if(heading)t.setTypeface(null,1);box.addView(t);}private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
}
